#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Generate self-contained cases from the frozen pure planner and UI adapters."""
import argparse
from pathlib import Path
ROOT = Path(__file__).resolve().parent

def generated(adapter):
    head = '''// SPDX-License-Identifier: GPL-3.0-or-later
// Generated by build.py. Prepared for native validation, not a success receipt.
TestCase {
    id: qa
    name: 'CurrentVisiblePatternCompletion'
    when: activity.visible && activity.numberOfLevel>0
    property var boards: []
    property var evidence: ({})
    property var registry: ({})
    property int wins: 0
    property int actions: 0
    property string activityName: ''
    Connections {target: bonus; function onWin() {qa.wins++;}}
'''
    parts = [(ROOT/name).read_text() for name in ['planner.js', adapter+'.js', 'common.js']]
    return head + '\n'.join(parts) + '\n}\n'

if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    for adapter in ['redraw', 'mosaic']:
        target = ROOT/('complete-'+adapter+'.qml')
        expected = generated(adapter)
        if args.check:
            if not target.is_file() or target.read_text()!=expected:
                raise SystemExit('Generated case differs: '+str(target))
        else:
            target.write_text(expected)
